window.Fixtures.applyResolvedPlayers=function(actaId,rows){this.ensureReportPlayers(actaId);let count=0;for(const row of Array.isArray(rows)?rows:[]){const rowKey=this.playerKey(row?.name),rowSig=this.playerSignature(row?.name),player=(this.reportData?.players||[]).find(p=>this.playerKey(p.name)===rowKey||(rowSig&&this.playerSignature(p.name)===rowSig));if(!player)continue;let url=this.safeProfileUrl(row?.url||'');const rfafId=String(row?.player_id||row?.rfaf_id||'').replace(/^-/,''),primary=String(row?.primary||'5000274').replace(/\D/g,'')||'5000274',photo=this.safePlayerPhoto(row?.photo||'','https://www.rfaf.es/pnfg/NPcd/');if(photo)player.photo=photo;if(!url&&/^\d{1,12}$/.test(rfafId))url='https://www.rfaf.es/pnfg/NPcd/NFG_EstadisticasJugador?cod_primaria='+encodeURIComponent(primary)+'&jugador='+encodeURIComponent(rfafId)+'&codacta='+encodeURIComponent(String(actaId))+'&nueva_ventana=';if(!url&&!photo)continue;if(url){const meta=this.profileMeta(url,actaId);player.profile_url=url;player.rfaf_id=meta.rfaf_id||rfafId;player.acta_id=meta.acta_id||String(actaId);player.primary=meta.primary||primary;player._profileLoaded=false}count++}const pending=this._rfafPending?.[String(actaId)];if(pending){delete this._rfafPending[String(actaId)];pending.resolve(count>0)}return count};
window.Fixtures.resolveRfafPlayers=function(actaId=''){this.ensureReportPlayers(actaId);const unresolved=(this.reportData?.players||[]).filter(p=>!/^\d{1,12}$/.test(String(p.rfaf_id||''))||!this.safePlayerPhoto(p.photo));if(!unresolved.length)return Promise.resolve(true);if(!window.RfafResolver||typeof window.RfafResolver.resolveActaPlayers!=='function')return Promise.resolve(false);const key=String(actaId),active=this._rfafPending[key];if(active)return active.promise;let finish;const promise=new Promise(resolve=>{finish=resolve}),timer=setTimeout(()=>{if(this._rfafPending[key])delete this._rfafPending[key];finish(false)},18000);const resolve=value=>{clearTimeout(timer);finish(value)};this._rfafPending[key]={promise,resolve};try{window.RfafResolver.resolveActaPlayers(key,JSON.stringify(unresolved.map(p=>p.name)))}catch(e){delete this._rfafPending[key];clearTimeout(timer);finish(false)}return promise};
const baseLoadReport=window.Fixtures.loadReport;
window.Fixtures.loadReport=async function(id,refresh=false){await baseLoadReport.call(this,id,refresh);if(this.reportData?.html){const parsed=this.parseReportPlayers(this.reportData.html,id);if(parsed.length){const existing=new Map((this.reportData.players||[]).map(p=>[this.playerKey(p.name),p]));for(const p of parsed)existing.set(this.playerKey(p.name),Object.assign({},existing.get(this.playerKey(p.name))||{},p));this.reportData.players=[...existing.values()]}}this.ensureReportPlayers(id);for(const p of this.reportData?.players||[]){const meta=this.profileMeta(p.profile_url,id);p.rfaf_id=p.rfaf_id||meta.rfaf_id;p.acta_id=p.acta_id||meta.acta_id;p.stats=Array.isArray(p.stats)?p.stats:[]}};
window.Fixtures._rfafProfilePending={};
window.Fixtures.applyResolvedProfile=function(playerId,data){const player=(this.reportData?.players||[]).find(p=>String(p.id)===String(playerId));if(player&&data&&typeof data==='object'){if(data.photo)player.photo=data.photo;if(Array.isArray(data.stats))player.stats=data.stats;player.profile_updated_at=data.updated_at||player.profile_updated_at||'';player._photoLoaded=!!player.photo;player._profileLoaded=!!player.stats?.length}const pending=this._rfafProfilePending?.[String(playerId)];if(pending){delete this._rfafProfilePending[String(playerId)];pending.resolve(!!player?._profileLoaded)}return !!player?._profileLoaded};
window.Fixtures.resolveRenderedPlayerProfile=function(player,actaId=''){if(!player||!this.safeProfileUrl(player.profile_url)||!window.RfafResolver||typeof window.RfafResolver.resolvePlayerProfile!=='function')return Promise.resolve(false);const key=String(player.id),active=this._rfafProfilePending[key];if(active)return active.promise;let finish;const promise=new Promise(resolve=>{finish=resolve}),timer=setTimeout(()=>{if(this._rfafProfilePending[key])delete this._rfafProfilePending[key];finish(false)},22000),resolve=value=>{clearTimeout(timer);finish(value)};this._rfafProfilePending[key]={promise,resolve};try{window.RfafResolver.resolvePlayerProfile(player.profile_url,key)}catch(e){delete this._rfafProfilePending[key];clearTimeout(timer);finish(false)}return promise};
window.Fixtures.loadPlayerProfile=async function(player,actaId=''){if(!player)return false;if(player._profileLoaded&&Array.isArray(player.stats)&&player.stats.length)return true;let meta=this.profileMeta(player.profile_url,actaId);player.rfaf_id=player.rfaf_id||meta.rfaf_id;player.acta_id=player.acta_id||meta.acta_id||String(actaId||'');player.primary=player.primary||meta.primary||'5000274';if(!/^\d{1,12}$/.test(player.rfaf_id||'')){await this.resolveRfafPlayers(actaId);meta=this.profileMeta(player.profile_url,actaId);player.rfaf_id=player.rfaf_id||meta.rfaf_id;player.acta_id=player.acta_id||meta.acta_id||String(actaId||'');player.primary=player.primary||meta.primary||'5000274'}if(!/^\d{1,12}$/.test(player.rfaf_id||'')||!/^\d{1,12}$/.test(player.acta_id||''))return false;if(location.hostname==='appassets.androidplatform.net'&&window.RfafResolver&&typeof window.RfafResolver.resolvePlayerProfile==='function'){const rendered=await this.resolveRenderedPlayerProfile(player,actaId);if(rendered)return true}if(location.hostname!=='appassets.androidplatform.net')return false;try{const r=await fetch('rfaf-player/'+encodeURIComponent(player.rfaf_id)+'.json?acta='+encodeURIComponent(player.acta_id)+'&primary='+encodeURIComponent(player.primary||'5000274'),{cache:'no-store'}),data=await r.json();if(data.html){const parsed=this.parsePlayerProfileHtml(data.html,player);if(parsed.photo)player.photo=parsed.photo;if(parsed.stats.length)player.stats=parsed.stats;player.profile_updated_at=data.updated_at||player.profile_updated_at||'';player._photoLoaded=!!player.photo;player._profileLoaded=!!player.stats.length;return player._profileLoaded}}catch(e){}return false};
window.Fixtures.enrichReportPlayers=async function(actaId=''){const beforeActa=new Map((this.reportData?.players||[]).map(p=>[String(p.id),p.photo||'']));await this.resolveRfafPlayers(actaId);let changed=(this.reportData?.players||[]).filter(p=>(p.photo||'')!==(beforeActa.get(String(p.id))||'')).length;const players=(this.reportData?.players||[]).filter(p=>/^\d{1,12}$/.test(String(p.rfaf_id||''))&&!p._profileLoaded);for(let i=0;i<players.length;i+=2){const chunk=players.slice(i,i+2),before=chunk.map(p=>p.photo||'');await Promise.all(chunk.map(p=>this.loadPlayerProfile(p,actaId)));chunk.forEach((p,j)=>{if((p.photo||'')!==before[j])changed++})}return changed};

window.Fixtures.findReportPlayer=function(name){const key=this.playerKey(name);return (this.reportData?.players||[]).find(p=>this.playerKey(p.name)===key||this.playerKey(this.personName(p.name))===key)||null};
window.Fixtures.playerAvatar=function(player,large=false){const photo=this.safePlayerPhoto(player?.photo),name=this.personName(player?.name||''),initials=name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?';return photo?`<img class="acta-player-avatar ${large?'large':''}" src="${this.esc(photo)}" alt="Foto de ${this.esc(name)}" loading="eager" referrerpolicy="no-referrer">`:`<span class="acta-player-avatar acta-player-placeholder ${large?'large':''}" aria-hidden="true">${this.esc(initials)}</span>`};
window.Fixtures.decorateReportPlayers=function(html,actaId){if(!html||!this.reportData?.players?.length)return html;const root=document.createElement('div');root.innerHTML=html;for(const node of root.querySelectorAll('.acta-person strong,.acta-events strong,.acta-timeline-player strong')){if(node.querySelector('a[data-player-link]'))continue;const raw=node.getAttribute('title')||node.textContent,player=this.findReportPlayer(raw);if(!player)continue;const label=node.textContent.trim();node.removeAttribute('title');node.innerHTML=`<a class="acta-player-link" data-player-link href="#jugador=${this.esc(player.id)}&acta=${this.esc(actaId)}">${this.playerAvatar(player)}<span>${this.esc(label)}</span></a>`}return root.innerHTML};
window.Fixtures.player=function(id,actaId){const E=x=>this.esc(x),p=(this.reportData?.players||[]).find(x=>String(x.id)===String(id));if(!p)return '<div class="acta-toolbar"><button class="report-back" data-player-back data-acta="'+E(actaId)+'">← Volver al acta</button></div>'+CDM.empty('Jugador no disponible','No se han podido cargar los datos públicos de este jugador.','user');const m=(this.data.round_matches||this.data.matches).find(x=>{try{return new URL(x.acta_url).searchParams.get('CodActa')===String(actaId)}catch(e){return false}}),model=this.reportModel(this.reportData,m),key=this.playerKey(p.name);let side=-1,number='',status='';model.teams.forEach((t,i)=>{const starter=t.starters.find(x=>this.playerKey(x.name)===key),bench=t.bench.find(x=>this.playerKey(x.name)===key);if(starter){side=i;number=starter.number;status='Titular'}else if(bench){side=i;number=bench.number;status='Suplente'}});const goals=model.goals.filter(x=>this.playerKey(x.name)===key).length,cards=model.teams.flatMap(t=>t.cards).filter(x=>this.playerKey(x.name)===key).length,team=side>=0?model.teams[side].name:'';const stats=Array.isArray(p.stats)?p.stats:[];const tables=stats.length?stats.map((s,i)=>`<section class="acta-panel player-rfaf-section"><div class="acta-panel-title"><h2>${E(i===0?'Estadísticas de la competición':s.title||'Datos de competición')}</h2></div><div class="report-table-wrap"><table class="report-table"><tbody>${(s.rows||[]).map(r=>'<tr>'+r.map(c=>'<td>'+E(c)+'</td>').join('')+'</tr>').join('')}</tbody></table></div></section>`).join(''):'<section class="acta-panel"><p class="acta-empty">La RFAF no ha publicado todavía estadísticas adicionales para este perfil.</p></section>';return `<div class="acta-toolbar"><button class="report-back" data-player-back data-acta="${E(actaId)}">← Volver al acta</button></div><section class="player-rfaf-hero">${this.playerAvatar(p,true)}<div><span>PERFIL RFAF</span><h1>${E(this.personName(p.name))}</h1><p>${E(team||'Jugador federado')}</p></div></section><section class="player-match-stats"><div><strong>${E(number||'–')}</strong><small>DORSAL</small></div><div><strong>${E(status||'–')}</strong><small>PARTICIPACIÓN</small></div><div><strong>${E(goals)}</strong><small>GOLES EN EL ACTA</small></div><div><strong>${E(cards)}</strong><small>TARJETAS EN EL ACTA</small></div></section>${tables}<p class="acta-source">Foto y estadísticas acumuladas de la competición obtenidas de RFAF${p.profile_updated_at?' · '+E(new Date(p.profile_updated_at).toLocaleString('es-ES')):''}</p>`};

document.addEventListener('error',e=>{const img=e.target;if(img.tagName==='IMG'&&img.dataset.crestSource&&!img.dataset.retried){img.dataset.retried='1';try{const u=new URL(img.dataset.crestSource);if(u.protocol==='https:'&&u.hostname==='rfaf.filesnovanet.es'&&u.pathname.startsWith('/pnfg/pimg/Clubes/'))img.src=u.href;}catch(e){}}},true);

